(() => {
  const state = window.__vibemux_ui_smoke;
  const query = selector => {
    const node = document.querySelector(selector);
    if (!node) throw new Error('Missing control: ' + selector);
    return node;
  };
  const set = (selector, value) => {
    const node = query(selector);
    if (node.type === 'checkbox') node.checked = value;
    else node.value = value;
    node.dispatchEvent(new Event('input', {bubbles: true}));
    node.dispatchEvent(new Event('change', {bubbles: true}));
  };
  const click = (text, selector = 'button') => {
    const node = [...document.querySelectorAll(selector)].find(item => item.textContent.trim() === text);
    if (!node || node.disabled) throw new Error('Unavailable action: ' + text);
    node.click();
  };
  const poll = (slot, command, predicate) => {
    const current = state[slot] ??= {pending: false, value: null, error: null};
    if (current.value && predicate(current.value)) return true;
    if (current.error && current.error.code !== 'provider_profiles_busy') throw new Error(command + ': ' + JSON.stringify(current.error));
    if (!current.pending) {
      current.pending = true;
      window.__TAURI_INTERNALS__.invoke(command).then(value => { current.value = value; current.error = null; })
        .catch(error => { current.error = error; }).finally(() => { current.pending = false; });
    }
    return false;
  };
  state.tools = {query, set, click, poll};
  return true;
})()

(() => {
  const state = window.__vibemux_ui_smoke;
  state.refusals = {done:false, passed:false};
  void (async () => {
    const invoke = (command, args) => window.__TAURI_INTERNALS__.invoke(command, args);
    const before = await invoke('provider_profiles_get');
    const results = [];
    for (const kind of ['url', 'secret']) {
      const config = JSON.parse(JSON.stringify(before.config));
      if (kind === 'url') config.profiles[0].base_url = 'http://remote.example.test/v1';
      else config.profiles[0].api_key = 'synthetic-do-not-store';
      try { await invoke('provider_profiles_set', {config}); results.push('accepted'); }
      catch (error) { results.push(error?.code ?? String(error)); }
    }
    const after = await invoke('provider_profiles_get');
    state.refusals = {done:true, passed:results[0] === 'provider_profiles_invalid_base_url' && results[1] === 'provider_profiles_invalid_document' && JSON.stringify(before) === JSON.stringify(after), results};
  })().catch(error => { state.refusals = {done:true, passed:false, error:String(error)}; });
  return true;
})()

