(() => {
  const body = getComputedStyle(document.body);
  const sidebar = document.querySelector('[aria-label="Conversation sidebar"]');
  return {
    url:location.href, user_agent:navigator.userAgent,
    secure_context:window.isSecureContext, web_locks:typeof navigator.locks?.request === 'function',
    public_tauri_global:typeof window.__TAURI__,
    theme:document.documentElement.dataset.theme, interface:document.documentElement.dataset.interface,
    body_font:body.fontFamily, body_color:body.color,
    sidebar_width:sidebar?.getBoundingClientRect().width,
    scripted_frames:document.querySelectorAll('iframe[srcdoc]').length,
    raw_key_inputs:document.querySelectorAll('[aria-label="API key"]').length,
    profile_count:document.querySelectorAll('fieldset.provider-profile').length,
    selected_profile:document.querySelector('#orchestrator_profile')?.value,
    page_text:document.body.innerText.slice(0,6000),
    read_settings:window.__vibemux_ui_smoke.private_fields?.value
  };
})()
